<script setup lang="ts">
import {computed,ref,watch,onBeforeUnmount} from 'vue';import {useLab} from '../store';import type {Simulation} from '../api';import {cycleEdges} from '../animation/timeline';import {usePlayback} from '../animation/usePlayback';import MotionControls from './MotionControls.vue';import GraphView from './GraphView.vue';
const lab=useLab();const view=lab.workspace?.view;const motion=view&&typeof view==='object'&&!Array.isArray(view)?view.motion:null;
const props=defineProps<{result:Simulation,source:string}>();const emit=defineEmits<{line:[number|null]}>();const count=computed(()=>props.result.steps.length);const playback=usePlayback(count);const {index,progress,playing,speed}=playback;const reduced=ref(motion&&typeof motion==='object'&&!Array.isArray(motion)&&typeof motion.reduced==='boolean'?motion.reduced:matchMedia('(prefers-reduced-motion: reduce)').matches);const focus=ref(false);const step=computed(()=>props.result.steps[index.value]);const previous=computed(()=>props.result.steps[index.value-1]);
const nodes=computed(()=>props.result.analysis.transactions.map(id=>({id,label:id,detail:'事务泳道'})));const visited=computed(()=>new Set(props.result.steps.slice(0,index.value+1).filter(s=>s.status!=='waiting').map(s=>s.source_line-1)));
const edges=computed(()=>props.result.analysis.edges.filter(e=>visited.value.has(e.first)&&visited.value.has(e.second)).filter((e,i,a)=>a.findIndex(x=>x.from===e.from&&x.to===e.to)===i).map(e=>({source:e.from,target:e.to,label:e.item})));
const allEdges=computed(()=>props.result.analysis.edges.filter((e,i,a)=>a.findIndex(x=>x.from===e.from&&x.to===e.to)===i).map(e=>({source:e.from,target:e.to,label:e.item})));
const allWaitEdges=computed(()=>props.result.steps.flatMap(s=>s.waits).filter(([a,b],i,all)=>all.findIndex(([c,d])=>a===c&&b===d)===i).map(([source,target])=>({source,target,label:'等待锁'})));
const danger=computed(()=>{const cycle=props.result.analysis.cycle;const pairs=cycle.slice(0,-1).map((id,i)=>`${id}:${cycle[i+1]}`);return pairs.length&&pairs.every(p=>edges.value.some(e=>`${e.source}:${e.target}`===p))?pairs:[];});
const waitEdges=computed(()=>step.value?.waits.map(([source,target])=>({source,target,label:'等待锁'}))??[]);const operation=computed(()=>step.value?.operation.split(' ')[0]??'');
const waitDanger=computed(()=>cycleEdges(waitEdges.value));
const removedLocks=computed(()=>previous.value?.locks.filter(l=>!step.value?.locks.includes(l))??[]);
watch(reduced,value=>{if(lab.workspace){const old=lab.workspace.view;lab.workspace.view={...(old&&typeof old==='object'&&!Array.isArray(old)?old:{}),motion:{detail:motion&&typeof motion==='object'&&!Array.isArray(motion)?motion.detail??'sample':'sample',reduced:value}};lab.dirty=true;}});onBeforeUnmount(()=>emit('line',null));
watch(()=>props.result,()=>playback.seek(0));watch(()=>step.value?.source_line,line=>emit('line',line??null),{immediate:true});
</script>
<template><div class="trace-view" :class="{'focus-view':focus}"><div class="trace-heading"><strong>事务如何交错发生</strong><div class="toolbar"><label class="check"><input v-model="reduced" type="checkbox">减少动态效果</label><button @click="focus=!focus">{{focus?'退出专注':'专注演示 ↗'}}</button></div></div><template v-if="step"><MotionControls :index="index" :count="count" :progress="progress" :playing="playing" :speed="speed" :label="`${step.tx} · ${step.operation}`" @seek="playback.seek($event)" @toggle="playback.toggle" @speed="speed=$event"/><div class="transaction-lanes"><div v-for="tx in result.analysis.transactions" :key="tx" class="transaction-lane" :class="{current:step.tx===tx,waiting:step.tx===tx&&step.status==='waiting'}"><b>{{tx}}</b><p>{{step.tx===tx?(step.status==='waiting'?'等待锁':operation==='rollback'?'回滚版本':operation==='commit'?'提交并释放锁':step.operation):'本事件未操作'}}</p><div v-if="step.tx===tx" class="transaction-pulse"><i :style="{transform:`translateX(${reduced?0:progress*230}%)`}"/></div></div></div><div class="expression-highlight"><span>第 {{step.source_line}} 行</span><code>{{source.split('\n')[step.source_line-1]}}</code></div><div class="notice" :class="{warning:step.status==='waiting'}">{{step.message}}</div><div class="schedule-graphs"><section><h4>截至当前事件的冲突优先图</h4><GraphView :nodes="nodes" :edges="allEdges" :visible-edges="edges.map(e=>`${e.source}:${e.target}`)" :selected="step.tx" :progress="progress" :reduced="reduced" :danger-edges="danger"/><div v-if="danger.length" class="notice warning">已形成冲突环：{{result.analysis.cycle.join(' → ')}}</div></section><section v-if="allWaitEdges.length"><h4>当前等待关系</h4><GraphView :nodes="nodes" :danger-edges="waitDanger" :edges="allWaitEdges" :visible-edges="waitEdges.map(e=>`${e.source}:${e.target}`)" :selected="step.tx" :active-edges="waitEdges.map(e=>`${e.source}:${e.target}`)" :progress="progress" :reduced="reduced"/><div v-if="waitDanger.length" class="notice error">死锁：等待环 {{waitDanger.map(e=>e.replace(':',' → ')).join('，')}}</div></section></div><div class="state-columns"><section class="state-card"><h4>数据库 → 局部变量 → 数据库</h4><div v-for="(value,key) in step.data" :key="key" class="state-change" :class="{changed:step.changes.some(c=>c.target===key)}"><code>{{key}}</code><template v-if="step.changes.some(c=>c.target===key)"><del>{{step.changes.find(c=>c.target===key)?.before}}</del><span>→</span></template><strong>{{value}}</strong></div><div v-for="change in step.changes.filter(c=>c.after==='已撤销')" :key="change.target" class="state-change"><code>{{change.target}}</code><del>{{change.before}}</del><strong>已撤销</strong></div></section><section class="state-card"><h4>局部变量 · 读取与计算</h4><div v-for="(vars,tx) in step.locals" :key="tx"><b>{{tx}}</b><div v-for="(value,key) in vars" :key="key" class="state-change" :class="{changed:previous?.locals[tx]?.[key]!==value}"><code>{{key}}</code><strong>{{value}}</strong></div></div><p v-if="!Object.keys(step.locals).length" class="muted">尚无读取</p></section></div><div class="state-card"><h4>锁的获得与释放</h4><p v-for="lock in step.locks" :key="lock" :class="{success:!previous?.locks.includes(lock)}">{{previous?.locks.includes(lock)?'持有':'＋ 获得'}} {{lock}}</p><p v-for="lock in removedLocks" :key="lock" class="warning">− 释放 <del>{{lock}}</del></p><p v-if="!step.locks.length&&!removedLocks.length" class="muted">当前没有锁</p></div><details class="state-card"><summary>冻结版本历史</summary><p v-for="v in step.versions" :key="v" :class="{success:!previous?.versions.includes(v)}">{{v}}</p></details><details class="state-card"><summary>完整调度 · 当前行高亮</summary><div class="model-source"><div v-for="(line,i) in source.split('\n')" :key="i" :class="{'schedule-line-current':i+1===step.source_line}"><small>{{i+1}}</small>{{line}}</div></div></details></template></div></template>
